package com.smarttask.controller;
import com.smarttask.entity.Task;import com.smarttask.repository.UserRepository;import com.smarttask.service.TaskService;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.time.*;import java.util.*;
@RestController @RequestMapping("/api/dashboard") public class DashboardController {private final TaskService tasks;private final UserRepository users;public DashboardController(TaskService t,UserRepository u){tasks=t;users=u;}@GetMapping public Map<String,Object> get(Authentication a){var all=tasks.raw(users.findByEmail(a.getName()).orElseThrow().getId());LocalDate today=LocalDate.now();long done=all.stream().filter(t->t.getStatus()==Task.Status.DONE).count();long open=all.size()-done;long overdue=all.stream().filter(t->t.getDueDate()!=null&&t.getDueDate().isBefore(today)&&t.getStatus()!=Task.Status.DONE).count();long todayCount=all.stream().filter(t->today.equals(t.getDueDate())&&t.getStatus()!=Task.Status.DONE).count();var trends=new ArrayList<Map<String,Object>>();for(int i=6;i>=0;i--){LocalDate day=today.minusDays(i);long count=all.stream().filter(t->t.getCompletedAt()!=null&&t.getCompletedAt().atZone(ZoneId.systemDefault()).toLocalDate().equals(day)).count();trends.add(Map.of("date",day.toString(),"completed",count));}var upcoming=all.stream().filter(t->t.getDueDate()!=null&&!t.getDueDate().isBefore(today)&&t.getStatus()!=Task.Status.DONE).sorted(Comparator.comparing(Task::getDueDate)).limit(5).map(com.smarttask.dto.ApiDtos.TaskView::of).toList();var recent=all.stream().limit(5).map(com.smarttask.dto.ApiDtos.TaskView::of).toList();return Map.of("total",all.size(),"open",open,"completed",done,"overdue",overdue,"dueToday",todayCount,"completionRate",all.isEmpty()?0:Math.round(done*100.0/all.size()),"trend",trends,"upcoming",upcoming,"recent",recent);}}
